import { Client } from '@elastic/elasticsearch';

const esClient = new Client({ node: 'http://localhost:9200' });
const INDEX = 'products';

describe('product search integration', () => {
  beforeEach(async () => {
    await esClient.indices.create({ index: INDEX });
  });

  afterEach(async () => {
    await esClient.indices.delete({ index: INDEX });
  });

  it('finds the seeded document', async () => {
    // Seed a single product document into the index.
    await esClient.index({
      index: INDEX,
      document: { id: 'p-1', name: 'Wireless Mouse' },
    });

    // Search for it right away — no wait for the index to settle.
    const result = await esClient.search({
      index: INDEX,
      query: { match: { name: 'Wireless Mouse' } },
    });

    // Teammate says this intermittently comes back 0 instead of 1,
    // and assumes the write above must have been lost.
    expect(result.hits.total.value).toBe(1);
  });
});
